// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'TU-USUARIO/meridiano-motor',                    // repositorio donde corre el motor (GitHub Actions)
  github_rama: 'main',
  supabase_url: 'https://xxxxxxxx.supabase.co',
  hoja_datos_id: 'ID-de-la-hoja-de-Google-Sheets',               // lo que va entre /d/ y /edit en la URL de la hoja
  panel_url: 'https://meridiano-panel.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',                           // responsable de la hoja de datos (avisos de la carga)
  modelo_ia: 'claude-sonnet-5-5',
  // MODO DEMO (datos ficticios): todos los correos van al buzón de pruebas, con el destinatario real en el asunto.
  // Los correos salen de la cuenta de Gmail conectada en n8n; el buzón de pruebas puede ser esa misma cuenta (con alias +demo).
  modo_demo: true,
  buzon_demo: 'TU-CUENTA+demo@gmail.com',
} }];

// Webhook de base de datos de Supabase: { type, table, record } por cada fila nueva de eventos_propuesta.
// La traza ya está guardada en Supabase; aquí solo interesan los cierres, para avisar a dirección si procede.
return $('Evento registrado en Supabase').all()
  .map(i => i.json.body || i.json)
  .filter(b => b.table === 'eventos_propuesta' && b.type === 'INSERT' && b.record && b.record.accion === 'cerrar')
  .map(b => ({ json: { propuesta_id: b.record.propuesta_id, usuario: b.record.usuario, fecha: b.record.creado_en } }));

// Cierres que requieren a dirección: cuenta clave perdida, cuenta marcada para dirección no recuperada, pérdida por reclamación.
const cierres = $('Solo cierres').all().map(i => i.json);
return $input.all().map((it, k) => {
  const r = ((it.json || {}).body || [])[0];
  if (!r) return null;
  const quien = (cierres[k] || {}).usuario || 'Un comercial';
  const motivos = [];
  if (r.cuenta_clave && r.estado_confirmado_comercial === 'Perdido') motivos.push('cuenta clave perdida');
  if (r.requiere_direccion && r.estado_confirmado_comercial !== 'Activo') motivos.push('cuenta marcada para dirección sin recuperar');
  if (r.motivo_confirmado === 'servicio_reclamacion' && r.estado_confirmado_comercial === 'Perdido') motivos.push('pérdida por reclamación');
  if (!motivos.length) return null;
  return { json: {
    asunto: `Meridiano · ${motivos.join(', ')}: ${r.razon_social}`,
    texto: `${quien} ha cerrado la propuesta de ${r.razon_social} (${r.id_cliente}), semana del ${String(r.fecha_corte).slice(0, 10)}.\n\n` +
      `Estado confirmado: ${r.estado_confirmado_comercial}\nMotivo confirmado: ${r.motivo_confirmado}\n` +
      `Diagnóstico del sistema correcto: ${r.diagnostico_correcto}\nFacturación en riesgo: ${r.facturacion_en_riesgo} €\n` +
      `Comentario: ${r.comentario_comercial || '—'}\n\nHistorial completo de la propuesta en el panel. Aviso generado por: ${motivos.join('; ')}.`,
  } };
}).filter(Boolean);
